#include "os_structures.h"
#include <assert.h>
#include <stdio.h>
enum { N=10000 };
int main(void){OsScheduler*os=os_create(20000);assert(os&&os_validate(os));OsPid pids[N];for(int i=0;i<N;++i)assert(os_spawn(os,(uint8_t)(i%OS_PRIORITY_LEVELS),&pids[i]));assert(os_process_count(os)==N);for(int p=0;p<OS_PRIORITY_LEVELS;++p)assert(os_ready_count(os,(uint8_t)p)==N/OS_PRIORITY_LEVELS);assert(os_validate(os));for(int i=0;i<1000;++i){OsPid pid=0;bool did=false;assert(os_dispatch(os,&pid,&did)&&did);OsProcState st;uint8_t pr;assert(os_get_state(os,pid,&st,&pr)&&st==OS_PROC_RUNNING&&pr==0U);if((i%3)==0)assert(os_block(os,pid));else assert(os_yield(os,pid));}assert(os_validate(os));for(int i=0;i<N;++i){OsProcState st;if(os_get_state(os,pids[i],&st,NULL)&&st==OS_PROC_BLOCKED)assert(os_wake(os,pids[i]));}assert(os_validate(os));OsPid running=0;bool did=false;assert(os_dispatch(os,&running,&did));if(did)assert(os_yield(os,running));OsPid stale=pids[0];assert(os_terminate(os,stale));OsPid replacement=0;assert(os_spawn(os,1,&replacement));assert(replacement!=stale);OsProcState st;assert(!os_get_state(os,stale,&st,NULL));assert(os_set_priority(os,replacement,0));assert(os_validate(os));printf("OS structures tests passed; active=%zu ready0=%zu\n",os_process_count(os),os_ready_count(os,0));os_free(os);return 0;}
